mapper.select:
select * from insp_checklist_item
where tenant_id = #{tenantId}
  and template_id = #{templateId}
  and deleted = 0
order by sort_order asc, id asc

mapper.update:
update insp_checklist_item
set deleted = 1, updated_at = now()
where tenant_id = #{tenantId}
  and template_id = #{templateId}
  and deleted = 0
